import{_ as l,o as e,c as i,ag as a}from"./chunks/framework.DXGyWiRo.js";const _=JSON.parse('{"title":"知识点8：人工智能与机器学习","description":"","frontmatter":{"title":"知识点8：人工智能与机器学习"},"headers":[],"relativePath":"high-school-it/knowledge-8.md","filePath":"high-school-it/knowledge-8.md"}'),o={name:"high-school-it/knowledge-8.md"};function r(n,t,s,d,h,u){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="知识点8-人工智能与机器学习" tabindex="-1">知识点8：人工智能与机器学习 <a class="header-anchor" href="#知识点8-人工智能与机器学习" aria-label="Permalink to &quot;知识点8：人工智能与机器学习&quot;">​</a></h1><h2 id="一、机器学习方法" tabindex="-1">一、机器学习方法 <a class="header-anchor" href="#一、机器学习方法" aria-label="Permalink to &quot;一、机器学习方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">方法</th><th style="text-align:left;">特点</th><th style="text-align:left;">示例</th></tr></thead><tbody><tr><td style="text-align:center;">监督学习</td><td style="text-align:left;">使用带标签的数据训练</td><td style="text-align:left;">分类（识别可抓取/不可抓取）、回归（预测力量大小）</td></tr><tr><td style="text-align:center;">非监督学习</td><td style="text-align:left;">使用无标签的数据训练</td><td style="text-align:left;">聚类（对环境声音自动归类）、词向量训练</td></tr></tbody></table><h2 id="二、生成式人工智能" tabindex="-1">二、生成式人工智能 <a class="header-anchor" href="#二、生成式人工智能" aria-label="Permalink to &quot;二、生成式人工智能&quot;">​</a></h2><ul><li><strong>数据来源</strong>：企业内部数据、公开数据集、社交媒体数据等（不包含涉及国家机密的数据）</li><li><strong>价值与风险共存</strong>：帮助减轻人类工作负担 / 大数据可能带来隐私风险 / 可能产生虚假内容需要甄别</li></ul><hr><h2 id="三、真题" tabindex="-1">三、真题 <a class="header-anchor" href="#三、真题" aria-label="Permalink to &quot;三、真题&quot;">​</a></h2><p><strong>1.（2025-01，综合题一）</strong> 生成式人工智能的数据来源丰富多样。以下可以作为其数据来源的有（ ）（多选题，3分）</p><ul><li>A. 企业内部数据</li><li>B. 公开数据集</li><li>C. 社交媒体数据</li><li>D. 涉及国家机密的专业领域数据</li></ul><p><strong>2.（2025-01，综合题一）</strong> 词向量是词的语言学概念的向量表达，它能帮助生成式人工智能更好地理解人类语言。在训练词向量模型时，使用的是不带有标签的文本数据。训练模型使用的方法属于__________（选填：监督学习/非监督学习）。（填空题，2分）</p><p><strong>3.（2025-01，综合题一）</strong> 小申了解到，生成式人工智能相关技术通过与制造业、农业、医疗、教育等传统行业的融合，推动了产业转型升级，对社会经济发展产生了影响。这主要体现了信息社会特征中的（ ）（单选题，2分）</p><ul><li>A. 信息经济</li><li>B. 网络社会</li><li>C. 在线政务</li><li>D. 数字生活</li></ul><p><strong>4.（2025-01，综合题一）</strong> 小申学习之后，对人工智能的各方面有了新的思考。关于人工智能的影响，以下说法正确的有（ ）（多选题，3分）</p><ul><li>A. 人工智能可以帮助人类减轻工作负担，承担部分重复性劳动</li><li>B. 大数据推动了人工智能的发展，也可能带来个人信息泄露风险</li><li>C. 生成式人工智能可能会产生虚假内容，人们需要进一步甄别</li><li>D. 人工智能将减少人类追求知识的兴趣，生活变得枯燥无味</li></ul><p><strong>5.（浦东新区2025，综合题一）</strong> 小申发现恐龙展区的导览机器人可以通过结合人脸识别与年龄估计等技术，为不同年龄段的观众切换不同的讲解形象。请把左侧实线框与右侧虚线框连线，将人脸识别的关键步骤补充完整。（连线题，3分）</p><p>考点：人脸识别关键步骤——图像采集 → 人脸检测 → 特征提取 → 特征比对 → 识别结果</p><p><strong>6.（浦东新区2025，综合题一）</strong> 上海科技馆&quot;玄俑重生&quot;展项还原了考古现场：破碎的兵马俑残片散落在发掘坑中，机器人需在复杂环境下识别陶片与杂物，区分可抓取的文物碎片和易碎的脆弱部位，并将其精准拼合复位。在此过程中，机器人学习&quot;看见&quot;和&quot;抓取&quot;等能力，模拟了多种机器学习方法。下列关于该展项中可能应用的机器学习技术的描述，正确的是（ ）（多选题，3分）</p><ul><li>A. 机器人通过分析大量带有&quot;可抓取&quot;或&quot;不可抓取&quot;标签的物体图片来学习识别目标，这主要应用了监督学习中的分类方法。</li><li>B. 机器人所有技能的学习都必须在人类工程师预先编写好每一步动作规则的条件下才能实现。</li><li>C. 机器人对环境中未标记的各类声音（如掌声、脚步声）进行自动归类，这属于典型的非监督学习中的聚类任务。</li><li>D. 机器人抓取物体时预测需要施加的精确力量大小，这可以看作是一个监督学习中的回归问题。</li></ul><h3 id="答案" tabindex="-1">答案 <a class="header-anchor" href="#答案" aria-label="Permalink to &quot;答案&quot;">​</a></h3><ol><li>ABC</li><li>非监督学习</li><li>A</li><li>ABC</li><li>人脸识别关键步骤：图像采集 → 人脸检测 → 特征提取 → 特征比对 → 识别结果</li><li>ACD（B错在并非所有技能都需要预先编写规则，机器学习可以自主从数据中学习）</li></ol>',20)])])}const c=l(o,[["render",r]]);export{_ as __pageData,c as default};
